// Package artifacts collects files generated by an ORCA run for upload
// to the tracking backend.
package artifacts

import (
	"bytes"
	"errors"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"regexp"
	"strings"
	"sync"
	"time"

	"github.com/nkls-ai/dftstream/internal/levels"
)

var vibXYZRE = regexp.MustCompile(`\.v\d+\.xyz$`)

// Kind is an artifact kind as stored on the backend. A string type, so it
// crosses the Convex wire format verbatim (marshals as the plain string).
type Kind string

// Artifact kinds as stored on the backend.
const (
	KindInput        Kind = "input"
	KindStdout       Kind = "stdout"
	KindOutput       Kind = "output"
	KindProperty     Kind = "property"
	KindCube         Kind = "cube"
	KindGoatMinimum  Kind = "goat_minimum"
	KindGoatEnsemble Kind = "goat_ensemble"
	KindVibMode      Kind = "vibmode"
	KindTrajectory   Kind = "trj"
	KindOther        Kind = "other"
)

const (
	// InlinePreviewBytes is the head preview kept on the artifact row
	// itself. Bodies larger than this go to Convex file storage; the
	// preview lets the UI show something instantly while it fetches.
	InlinePreviewBytes = 16 * 1024
	// MaxTextContentBytes is the total amount of text we will store per
	// artifact. Past this we set the Truncated flag. Bodies above the
	// inline preview are uploaded whole to file storage, which is not
	// bound by the per-mutation document size limit.
	MaxTextContentBytes = 128 * 1024 * 1024 // 128 MB
	// MaxBytesForCollection bounds how large a file can be and still be
	// collected at all. Anything larger is skipped entirely.
	MaxBytesForCollection = 128 * 1024 * 1024 // 128 MB
)

// extLevel is the minimum level at which a given extension is included.
// Compound extensions (".property.txt") are handled in includeAtLevel.
var extLevel = map[string]levels.ArtifactLevel{
	".inp":    levels.ArtifactsIO,
	".out":    levels.ArtifactsIO,
	".xyz":    levels.ArtifactsEssential,
	".allxyz": levels.ArtifactsEssential,
	".interp": levels.ArtifactsEssential, // NEB per-iteration energy profiles (drives the path switcher)

	".property": levels.ArtifactsMedium,
	".bibtex":   levels.ArtifactsMedium,
	".log":      levels.ArtifactsMedium,
	".txt":      levels.ArtifactsMedium, // covers .property.txt via dual check
	".dat":      levels.ArtifactsMedium, // includes ORCA relaxed-scan surface data

	".engrad":   levels.ArtifactsAll,
	".opt":      levels.ArtifactsAll,
	".hess":     levels.ArtifactsAll,
	".uno":      levels.ArtifactsAll,
	".uco":      levels.ArtifactsAll,
	".gradient": levels.ArtifactsAll,
	".smd":      levels.ArtifactsAll,
	".cis":      levels.ArtifactsAll,
	".trj":      levels.ArtifactsAll,
	".plot":     levels.ArtifactsAll,
	".cube":     levels.ArtifactsMedium, // orbital / density cubes (post-processed; rendered in UI)
}

// hardExclude is files we never collect regardless of level: large or
// binary ORCA scratch files, plus working files (.tmp).
var hardExclude = map[string]bool{
	".gbw":           true,
	".densities":     true,
	".densitiesinfo": true,
	".scfp":          true,
	".scfr":          true,
	".pcgbw":         true,
	".pcgrad":        true,
	".bas":           true,
	".tmp":           true,
}

// includeAtLevel decides whether a file with the given name+size should
// be collected at the given level.
func includeAtLevel(name string, size int64, level levels.ArtifactLevel) bool {
	if level == levels.ArtifactsNone {
		return false
	}
	if size > MaxBytesForCollection {
		return false
	}
	low := strings.ToLower(name)
	ext := filepath.Ext(low)
	if hardExclude[ext] {
		return false
	}
	// Compound extensions: ".property.txt" is part of levels.ArtifactsMedium, not levels.ArtifactsAll.
	// ".property.json" rides with it — same content, machine-readable, and it
	// is what the run-end reconciliation checks our stdout parse against.
	if strings.HasSuffix(low, ".property.txt") || strings.HasSuffix(low, ".property.json") {
		return level >= levels.ArtifactsMedium
	}
	if strings.HasSuffix(low, ".relaxscanact.dat") || strings.HasSuffix(low, ".relaxscanscf.dat") {
		return level >= levels.ArtifactsEssential
	}
	required, known := extLevel[ext]
	if !known {
		// Unknown extension — only show at "all".
		return level >= levels.ArtifactsAll
	}
	return level >= required
}

// Artifact is the backend-agnostic record DFTStream stores per file.
//
// When the file is larger than InlinePreviewBytes:
//   - ContentText holds only the head preview
//   - Body holds the full body, which the tracker uploads to file storage
//   - Truncated is true iff the file was bigger than MaxTextContentBytes
type Artifact struct {
	Name        string
	Path        string
	Kind        Kind // one of the Kind* constants
	SizeBytes   int64
	MTime       time.Time
	ContentText string // head preview (may be the entire file)
	Truncated   bool
	Body        []byte // full body, uploaded to file storage; nil when the
	//  whole file fit in the inline preview (ContentText)
}

// CapWriter is an io.Writer that buffers at most a fixed number of bytes
// and silently discards the rest, recording the overflow. Use Snapshot to
// read the buffered content and overflow state.
//
// We bound the buffer because ORCA's stdout can grow to many MB for big
// jobs. The buffered content is what we surface in the UI's "stdout"
// artifact — operators can still get the full stream from their shell
// redirect (e.g. `> file.out`).
type CapWriter struct {
	mu       sync.Mutex
	buf      bytes.Buffer
	limit    int
	overflow bool
	total    int64
}

func NewCapWriter(limit int) *CapWriter { return &CapWriter{limit: limit} }

func (w *CapWriter) Write(p []byte) (int, error) {
	w.mu.Lock()
	defer w.mu.Unlock()
	w.total += int64(len(p))
	rem := w.limit - w.buf.Len()
	if rem <= 0 {
		w.overflow = true
		return len(p), nil
	}
	if rem >= len(p) {
		w.buf.Write(p)
		return len(p), nil
	}
	w.buf.Write(p[:rem])
	w.overflow = true
	return len(p), nil
}

// Snapshot returns the buffered bytes, whether input overflowed the
// buffer, and the total number of bytes written.
func (w *CapWriter) Snapshot() (string, bool, int64) {
	w.mu.Lock()
	defer w.mu.Unlock()
	return w.buf.String(), w.overflow, w.total
}

// textExtensions are extensions we always treat as text and inline.
var textExtensions = map[string]bool{
	".inp":         true,
	".out":         true,
	".txt":         true,
	".xyz":         true,
	".log":         true,
	".bibtex":      true,
	".property":    true,
	".dat":         true,
	".allxyz":      true,
	".trj":         true,
	".cis":         true,
	".engrad":      true,
	".hess":        true,
	".opt":         true,
	".smd":         true,
	".uno":         true,
	".gradient":    true,
	".pcgrad":      true,
	".plot":        true,
	".out.tmp":     true,
	".uco":         true,
	".scfgrad.tmp": true,
	".cube":        true,
	".interp":      true,
}

// Classify returns the artifact kind for a filename.
func classify(name, stem string) Kind {
	low := strings.ToLower(name)
	switch {
	case name == stem+".inp":
		return KindInput
	case strings.HasSuffix(low, ".property.txt"),
		strings.HasSuffix(low, ".property.json"),
		strings.HasSuffix(low, ".property"):
		return KindProperty
	case strings.HasSuffix(low, ".out"),
		strings.HasSuffix(low, ".log"):
		return KindOutput
	case strings.HasSuffix(low, ".globalminimum.xyz"):
		return KindGoatMinimum
	case strings.Contains(low, ".finalensemble") && strings.HasSuffix(low, ".xyz"):
		return KindGoatEnsemble
	case strings.HasSuffix(low, ".cube"):
		return KindCube
	case vibXYZRE.MatchString(low):
		return KindVibMode
	case strings.HasSuffix(low, "_trj.xyz"):
		return KindTrajectory
	default:
		return KindOther
	}
}

func isText(name string) bool {
	low := strings.ToLower(name)
	// Catch the compound ".property.*" names as text (plain ".json" is not
	// a text extension in general — ORCA writes other, larger .json files).
	if strings.HasSuffix(low, ".property.txt") || strings.HasSuffix(low, ".property.json") {
		return true
	}
	ext := filepath.Ext(low)
	return textExtensions[ext]
}

// Collect scans dir for files generated by a run (matching `<stem>.` or
// `<stem>_` prefix), modified at or after startedAt (with small slack).
// Files are filtered by `level`: anything below the cutoff is omitted.
//
// The returned slice is ALWAYS usable, error or not. Only a failure to
// read the directory itself yields no artifacts; a per-file problem
// (unstatable entry, unreadable body) leaves the rest of the manifest
// intact and is reported through the joined error. Callers must log that
// error and keep the artifacts — a run's whole record is not worth
// discarding because one file could not be read.
//
// A body we could not read is uploaded as a row with no content and
// Truncated set, never as a row that looks complete: an empty .out that
// silently claims to be the run's output is worse than an obviously
// partial one.
func Collect(dir, stem string, startedAt time.Time, level levels.ArtifactLevel) ([]Artifact, error) {
	entries, err := os.ReadDir(dir)
	if err != nil {
		return nil, err
	}
	cutoff := startedAt.Add(-2 * time.Second) // tolerate clock skew
	var out []Artifact
	var problems []error
	for _, e := range entries {
		if e.IsDir() {
			continue
		}
		name := e.Name()
		if !strings.HasPrefix(name, stem+".") && !strings.HasPrefix(name, stem+"_") {
			continue
		}
		info, err := e.Info()
		if err != nil {
			// Racing ORCA's own scratch cleanup makes this normal — the
			// entry can vanish between ReadDir and Info — but we cannot
			// size or time-filter what we cannot stat, so say so.
			problems = append(problems, fmt.Errorf("stat %s: %w", name, err))
			continue
		}
		if info.ModTime().Before(cutoff) {
			continue
		}
		if !includeAtLevel(name, info.Size(), level) {
			continue
		}
		path := filepath.Join(dir, name)
		art := Artifact{
			Name:      name,
			Path:      path,
			Kind:      classify(name, stem),
			SizeBytes: info.Size(),
			MTime:     info.ModTime(),
		}
		if isText(name) && info.Size() > 0 {
			b, err := readCapped(path, MaxTextContentBytes)
			if err != nil {
				art.Truncated = true
				problems = append(problems, fmt.Errorf("read %s: %w", name, err))
			} else {
				populateContent(&art, b, info.Size())
			}
		}
		out = append(out, art)
	}
	return out, errors.Join(problems...)
}

// ReadCapped reads at most MaxTextContentBytes from path.
//
// Anything staging a whole ORCA file into memory must come through here.
// A .out from a multi-week optimization runs to gigabytes, and a plain
// os.ReadFile of one puts the entire thing on the heap at once — the
// import path used to do exactly that. Pair it with the file's real size
// so the artifact is flagged Truncated when the cap bites.
func ReadCapped(path string) ([]byte, error) {
	return readCapped(path, MaxTextContentBytes)
}

// readCapped reads up to max bytes from path.
func readCapped(path string, max int) ([]byte, error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	// Read-only handle: a close failure cannot lose data, and the bytes
	// are already in hand.
	defer f.Close() //nolint:errcheck — read-only handle
	return io.ReadAll(io.LimitReader(f, int64(max)))
}

// FromStdout builds an artifact record from a CapWriter snapshot.
func FromStdout(name string, w *CapWriter) Artifact {
	content, overflow, total := w.Snapshot()
	art := Artifact{
		Name:      name,
		Path:      "",
		Kind:      KindStdout,
		SizeBytes: total,
		MTime:     time.Now(),
	}
	populateContent(&art, []byte(content), total)
	if overflow {
		// CapWriter dropped bytes mid-stream — flag explicitly even if
		// what we captured happens to fit in the inline preview.
		art.Truncated = true
	}
	return art
}

// AttachContent stores body on art using the same preview + chunk
// machinery as collected artifacts. Truncated is set when len(body)
// is below art.SizeBytes (caller didn't read the whole file).
func AttachContent(art *Artifact, body []byte) {
	populateContent(art, body, art.SizeBytes)
}

// populateContent keeps a head preview inline and, when the body is
// larger than the preview, stashes the full body for upload to file
// storage. Truncated is set if the source was larger than what we
// captured.
func populateContent(art *Artifact, body []byte, originalSize int64) {
	if len(body) <= InlinePreviewBytes {
		art.ContentText = string(body)
		art.Body = nil
		if originalSize > int64(len(body)) {
			art.Truncated = true
		}
		return
	}
	art.ContentText = string(body[:InlinePreviewBytes])
	art.Body = body
	if originalSize > int64(len(body)) {
		art.Truncated = true
	}
}
